import csv
import ast

with open("/app/dataset/tasks.csv") as f:
    valid_tasks = {int(r["task_id"]): r for r in csv.DictReader(f)}

with open("/app/dataset/timesheet.csv") as f:
    ts = list(csv.DictReader(f))

# Collect all invalid task IDs
invalid_tasks = set()
for r in ts:
    s = r["performed_tasks"].strip()
    if s.endswith("]") and not s.startswith("["):
        s = "[" + s
    elif s.startswith("[") and not s.endswith("]"):
        s = s + "]"
    try:
        tasks = ast.literal_eval(s)
        for t in tasks:
            if t not in valid_tasks:
                invalid_tasks.add(t)
    except:
        pass

print(f"Total distinct invalid task IDs: {len(invalid_tasks)}")
print("Sample invalid tasks:", sorted(invalid_tasks)[:20])

# Check if any invalid task ID is an anagram or digit-edit of a valid task ID
valid_ids = sorted(valid_tasks.keys())
print("Valid task IDs:", valid_ids)

for it in sorted(invalid_tasks)[:10]:
    s_it = str(it)
    matches = []
    for vt in valid_ids:
        s_vt = str(vt)
        diffs = sum(1 for c1, c2 in zip(s_it, s_vt) if c1 != c2) if len(s_it) == len(s_vt) else 99
        if sorted(s_it) == sorted(s_vt):
            matches.append((diffs, True, vt))
        elif diffs <= 1:
            matches.append((diffs, False, vt))
    print(f"Invalid {it}: possible matches -> {matches}")
'

