import csv
import ast

with open("/app/dataset/tasks.csv") as f:
    task_pay = {int(r["task_id"]): float(r["pay_per_completion"]) for r in csv.DictReader(f)}

with open("/app/dataset/timesheet.csv") as f:
    ts = list(csv.DictReader(f))

def parse_tasks(raw):
    s = raw.strip()
    if s.endswith("]") and not s.startswith("["):
        s = "[" + s
    elif s.startswith("[") and not s.endswith("]"):
        s = s + "]"
    return ast.literal_eval(s)

eid = "68011810139"
for r in ts:
    if r["employee_id"] == eid and r["date"] < "2025-04-01":
        tasks = parse_tasks(r["performed_tasks"])
        b1 = sum(task_pay.get(t, 0.0) for t in tasks)
        b2 = float(r["bonus"])
        if b1 != b2:
            print(f"Row {r['id']}, date {r['date']}: tasks={tasks}, b1={b1}, b2={b2}")
