import csv
import ast
from collections import defaultdict

with open("/app/dataset/employees.csv") as f:
    emp = {r["PESEL"]: float(r["hourly_rate"]) for r in csv.DictReader(f)}

with open("/app/dataset/tasks.csv") as f:
    task_pay = {int(r["task_id"]): float(r["pay_per_completion"]) for r in csv.DictReader(f)}

with open("/app/dataset/timesheet.csv") as f:
    ts = list(csv.DictReader(f))

corrupted_map = {
    "68011910138": "68011810139",
    "84731091580": "87031491580",
    "16102016795": "96102016751",
    "15720759071": "75020759171",
    "62020111425": "65020111422"
}

def parse_tasks(raw):
    s = raw.strip()
    if s.endswith("]") and not s.startswith("["):
        s = "[" + s
    elif s.startswith("[") and not s.endswith("]"):
        s = s + "]"
    try:
        return ast.literal_eval(s)
    except:
        return []

def get_billing_month(d):
    if d < "2025-04-01":
        return "2025-03"
    elif d < "2025-05-06":
        return "2025-04"
    elif d < "2025-06-03":
        return "2025-05"
    else:
        return "2025-06"

months = ["2025-03", "2025-04", "2025-05", "2025-06"]

def run_pipeline(dedup=True, map_corrupted=False, bonus_source="tasks", drop_invalid_dates=True):
    seen = set()
    rows = []
    for r in ts:
        key = (r["date"], r["hours_worked"], r["performed_tasks"], r["employee_id"], r["facility_id"], r["salary_amount"], r["bonus"])
        if dedup:
            if key in seen:
                continue
            seen.add(key)

        if drop_invalid_dates and r["date"] in ("2025-04-31", "2025-06-31"):
            continue

        eid = r["employee_id"]
        if eid not in emp:
            if map_corrupted and eid in corrupted_map:
                eid = corrupted_map[eid]
            else:
                continue

        r_copy = dict(r)
        r_copy["employee_id"] = eid
        rows.append(r_copy)

    salaries = {e: [0, 0, 0, 0] for e in sorted(emp.keys())}
    for r in rows:
        eid = r["employee_id"]
        m = get_billing_month(r["date"])
        m_idx = months.index(m)
        hw = float(r["hours_worked"])
        rate = emp[eid]
        if bonus_source == "tasks":
            tasks = parse_tasks(r["performed_tasks"])
            b = sum(task_pay.get(t, 0.0) for t in tasks)
        elif bonus_source == "bonus_col":
            b = float(r["bonus"])
        elif bonus_source == "bonus_col_pos":
            b = max(0.0, float(r["bonus"]))
        salaries[eid][m_idx] += hw * rate + b

    # round to int
    return {k: [int(round(v)) for v in vals] for k, vals in salaries.items()}

c1 = run_pipeline(dedup=True, map_corrupted=False, bonus_source="tasks")
c2 = run_pipeline(dedup=True, map_corrupted=True, bonus_source="tasks")
c3 = run_pipeline(dedup=True, map_corrupted=False, bonus_source="bonus_col")
c4 = run_pipeline(dedup=False, map_corrupted=False, bonus_source="tasks")

print("Config 1 (clean, exclude corrupted, tasks bonus):")
for k in list(c1.keys())[:3]:
    print(f"  {k}: {c1[k]}")

print("\nDifferences between C1 and C2 (map corrupted):")
diffs_c1_c2 = {k: (c1[k], c2[k]) for k in c1 if c1[k] != c2[k]}
print(f"Count of employees differing: {len(diffs_c1_c2)}")
for k, (v1, v2) in diffs_c1_c2.items():
    print(f"  {k}: C1={v1} vs C2={v2}")

print("\nDifferences between C1 and C3 (bonus col):")
diffs_c1_c3 = {k: (c1[k], c3[k]) for k in c1 if c1[k] != c3[k]}
print(f"Count of employees differing: {len(diffs_c1_c3)}")
for k, (v1, v2) in list(diffs_c1_c3.items())[:3]:
    print(f"  {k}: C1={v1} vs C3={v2}")

print("\nDifferences between C1 and C4 (no dedup):")
diffs_c1_c4 = {k: (c1[k], c4[k]) for k in c1 if c1[k] != c4[k]}
print(f"Count of employees differing: {len(diffs_c1_c4)}")
for k, (v1, v2) in list(diffs_c1_c4.items())[:3]:
    print(f"  {k}: C1={v1} vs C4={v2}")
